{
  "name": "是德科技 InfiniiVision X 系列示波器",
  "name_en": "Keysight InfiniiVision X Series Oscilloscope",
  "manufacturer": "Keysight Technologies",
  "description": "一类台式数字/混合信号示波器，用于实验室中观察、采集和分析电子信号波形，测量电压随时间的变化，检查各通道显示状态，并导出屏幕图像和波形数据。",
  "description_en": "A bench-top digital/mixed-signal oscilloscope used in laboratories to view, capture, and analyze electronic waveforms, measure voltage-versus-time behavior, check channel display status, and export screen images and waveform data.",
  "tag_hints": [
    "digital oscilloscope",
    "mixed-signal oscilloscope",
    "waveform acquisition",
    "time-domain measurement",
    "electronics debugging",
    "screen capture",
    "analog channel trace"
  ],
  "actions": [
    {
      "action_name": "auto-screenshot",
      "description": "采集当前示波器屏幕截图",
      "description_en": "Capture a screenshot of the current oscilloscope display."
    },
    {
      "action_name": "auto-channels",
      "description": "获取示波器可用通道列表",
      "description_en": "Get the list of available oscilloscope channels."
    },
    {
      "action_name": "auto-displayed",
      "description": "获取指定通道是否正在屏幕上显示",
      "description_en": "Get whether the specified channel is currently displayed on screen."
    },
    {
      "action_name": "auto-get_traces_from_displayed_channels",
      "description": "采集当前已显示通道的波形轨迹数据",
      "description_en": "Acquire waveform trace data from the channels currently displayed on screen."
    },
    {
      "action_name": "auto-trace",
      "description": "采集指定通道的波形轨迹数据",
      "description_en": "Acquire waveform trace data from the specified channel."
    }
  ]
}

